def overlap(s, e, a, b):
    return s < b and a < e

def has_conflict(m, st, en, machine_intervals, dt):
    for a, b in machine_intervals.get(m, []):
        if overlap(st, en, a, b):
            return True
    for a, b in dt.get(m, []):
        if overlap(st, en, a, b):
            return True
    return False

def earliest_feasible_time(m, anchor, dur, machine_intervals, dt, safety=200000):
    t = int(anchor)
    for _ in range(safety):
        if not has_conflict(m, t, t + dur, machine_intervals, dt):
            return t
        t += 1
    return t

