        if len(non_frozen_in_group) <= 3:
            perms = list(permutations(non_frozen_in_group))
        else:
            # Too many permutations, just use default
            perms = [tuple(non_frozen_in_group)]

        # For each permutation, interleave frozen ops at their original position
        group_orderings = []
        for perm in perms:
            # Merge frozen and non-frozen preserving frozen order
            ordering = list(frozen_in_group) + list(perm)
            group_orderings.append(ordering)
        group_perms.append(group_orderings)

    for ordering_combo in product(*group_perms):
        order = []
        for group_ordering in ordering_combo:
            order.extend(group_ordering)

        machine_intervals = {}
        new_schedule = {}
        shift_total = 0
        valid = True

        for (j, o) in order:
            base_r = base_map[(j, o)]
            base_start = base_r["start"]

            if o > 0:
                prev_end = new_schedule[(j, o-1)]["end"]
            else:
                prev_end = 0
            anchor = max(base_start, prev_end)

            if (j, o) in frozen_ops:
                m = base_r["machine"]
                d = allowed[(j,o)][m]
                st = base_start
                en = st + d
                conflict = has_conflict(m, st, en, machine_intervals, downtime)
                if conflict:
                    valid = False
                    break
                new_schedule[(j, o)] = {"job": j, "op": o, "machine": m, "start": st, "end": en, "dur": d}
                machine_intervals.setdefault(m, []).append((st, en))
            else:
                m = machine_choice[(j, o)]
                d = allowed[(j, o)][m]
                st = earliest_feasible_time(m, anchor, d, machine_intervals, downtime)
                en = st + d
                shift_total += abs(st - base_start)
                if shift_total > max_shift:
                    valid = False
                    break
                new_schedule[(j, o)] = {"job": j, "op": o, "machine": m, "start": st, "end": en, "dur": d}
                machine_intervals.setdefault(m, []).append((st, en))

        if not valid:
            continue

        makespan = max(r["end"] for r in new_schedule.values())
        count += 1

        if makespan < best_makespan:
            if validate(new_schedule, mc_count, shift_total):
                best_makespan = makespan
                best_overall = (dict(new_schedule), makespan, mc_count, shift_total)

print(f"\nTotal valid schedules evaluated: {count}")

if best_overall:
    ns, ms, mc, sh = best_overall
